const storageKey = "sauto-demo-v1";
function loadDemoData() { try { return { ...structuredClone(seed), ...JSON.parse(localStorage.getItem(storageKey) || "{}") }; } catch { return structuredClone(seed); } }
let data = loadDemoData();
let activeView = "dashboard";
let currentQuery = "";
let fleetFilter = "All vehicles";
let paymentFilter = "All payments";
let reportRange = "Month";
let authMode = "login";
let connectionDraft = null;
let editingId = null;
let apiSession = null;
let menuOpen = false;
const titles = { dashboard: "Overview", fleet: "Vehicles", drivers: "Drivers", documents: "Documents", payments: "Payments", billing: "Billing", reports: "Reports" };
const routes = { vehicles: "/api/vehicles", drivers: "/api/drivers", documents: "/api/documents", payments: "/api/payments", invoices: "/api/invoices" };

function saveDemo() { localStorage.setItem(storageKey, JSON.stringify(data)); }
function esc(value = "") { return String(value).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])); }
function money(value, compact = false) { return new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0, notation: compact ? "compact" : "standard" }).format(Number(value || 0)); }
function prettyDate(value, opts = { day: "numeric", month: "short", year: "numeric" }) { if (!value) return "—"; return new Intl.DateTimeFormat("en-IN", opts).format(new Date(`${value}T00:00:00`)); }
function dayDistance(value) { return Math.ceil((new Date(`${value}T23:59:59`).getTime() - Date.now()) / 86400000); }
function relativeDate(value) { const days = dayDistance(value); if (days < 0) return `${Math.abs(days)} days overdue`; if (days === 0) return "Due today"; return `In ${days} days`; }
function initials(name = "") { return name.split(/\s+/).slice(0, 2).map(n => n[0] || "").join("").toUpperCase(); }
function avatar(name, tone = "") { return `<span class="tiny-avatar ${tone}">${esc(initials(name))}</span>`; }
function filtered(items, fields) { const q = currentQuery.trim().toLowerCase(); return q ? items.filter(item => fields.some(field => String(item[field] ?? "").toLowerCase().includes(q))) : items; }
function modeLabel() { const button = $(".demo-pill"); if (!button) return; button.classList.toggle("live", Boolean(apiSession)); $("#connection-label").textContent = apiSession ? "Live data" : "Demo mode"; }
function documentCount() { return data.documents.filter(d => dayDistance(d.expiresOn) <= 30).length; }
function updateSidebarCounts() { const ready = data.vehicles.filter(v => v.status !== "Service").length; const availability = data.vehicles.length ? Math.round(ready / data.vehicles.length * 100) : 0; $("#vehicle-count").textContent = data.vehicles.length; $("#active-fleet-count").textContent = ready; $("#fleet-health-value").textContent = `${availability}%`; $("#fleet-health-bar").style.width = `${availability}%`; const alert = $(".nav-alert"); if (alert) alert.textContent = documentCount(); }
function render() { updateSidebarCounts(); modeLabel(); $$("[data-nav]").forEach(button => button.classList.toggle("active", button.dataset.nav === activeView)); $("[data-action='more-nav']")?.classList.toggle("active", ["documents", "payments", "billing", "reports"].includes(activeView)); $("#breadcrumb-current").textContent = titles[activeView]; renderContent(); }
function renderContent() { const root = $("#page-content"); if (!root) return; const views = { dashboard: dashboardView, fleet: fleetView, drivers: driversView, documents: documentsView, payments: paymentsView, billing: billingView, reports: reportsView }; root.innerHTML = (views[activeView] || dashboardView)(); }
function heading(kicker, title, subtitle, actions = "") { return `<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="heading-actions">${actions}</div></div>`; }
function button(label, action, primary = false, iconName = "") { return `<button class="button ${primary ? "primary" : ""}" data-action="${action}">${iconName ? svg(iconName) : ""}${esc(label)}</button>`; }
function statusPill(status) { const cls = status === "Available" || status === "Paid" || status === "Active" || status === "On route" ? "" : status === "Service" || status === "Overdue" ? "maintenance" : status === "Pending" || status === "Sent" || status === "Upcoming" || status === "Expiring" ? "pending" : "idle"; return `<span class="status ${cls}">${esc(status)}</span>`; }
function spark(points = "0,17 10,12 19,14 29,5 40,9 54,2") { return `<span class="sparkline"><svg viewBox="0 0 54 22" preserveAspectRatio="none"><path d="M${points}"/></svg></span>`; }
function stat(label, value, trend, foot, iconName, tone = "", trendDown = false, line = undefined) { return `<article class="stat-card ${tone}"><div class="stat-top"><span class="stat-label">${esc(label)}</span><span class="stat-icon ${tone}">${svg(iconName)}</span></div><div class="stat-value">${value}</div><div class="stat-foot"><span class="trend ${trendDown ? "down" : ""}">${esc(trend)}</span><span>${esc(foot)}</span></div>${spark(line)}</article>`; }
function hero() { return `<section class="hero-card"><div class="hero-copy"><div class="hero-kicker">Your transport day</div><h2>Every trip, in one place.</h2><p>See your vehicles, drivers, renewals and payments at a glance.</p><div class="hero-actions"><button class="button" data-nav="fleet">View vehicles ${svg("arrow")}</button><button class="hero-link" data-nav="reports">See reports ${svg("arrow")}</button></div></div><div class="hero-brand-watermark" aria-hidden="true"><img src="./sauto-original-logo.png" alt=""></div><div class="hero-art" aria-hidden="true"><div class="hero-orbit"></div><div class="hero-base"></div><div class="hero-stats"><span>On-time delivery</span><strong>96.8% <small>↗ 2.4%</small></strong></div><div class="hero-route-label">BENGALURU <b>— — —</b> MYSURU</div></div></section>`; }
function activityChart() { const points = reportRange === "Week" ? "0,85 45,62 90,72 135,45 180,56 225,22 270,39 315,14 360,29 405,10 450,17 495,4" : "0,96 45,83 90,88 135,55 180,65 225,49 270,62 315,25 360,41 405,18 450,31 495,8"; const area = `${points} 495,120 0,120`; const labels = reportRange === "Week" ? ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"] : ["01 Oct", "04 Oct", "07 Oct", "10 Oct", "13 Oct", "16 Oct", "20 Oct"];
  return `<svg class="chart-svg" viewBox="0 0 495 120" preserveAspectRatio="none" role="img" aria-label="Vehicle activity line chart"><defs><linearGradient id="chart-gradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#a9cf91" stop-opacity=".28"/><stop offset="1" stop-color="#a9cf91" stop-opacity="0"/></linearGradient></defs><path class="chart-gridline" d="M0 15H495M0 47H495M0 79H495M0 111H495"/><polygon class="chart-area" points="${area}"/><polyline class="chart-line" points="${points}"/><circle class="chart-dot" cx="315" cy="25" r="3.5"/><circle class="chart-dot" cx="495" cy="8" r="3.5"/></svg><div class="chart-xlabels">${labels.map(x => `<span>${x}</span>`).join("")}</div>`; }
function vehicleRows(items) { if (!items.length) return `<tr><td colspan="5"><div class="empty-state"><strong>No vehicles match</strong><p>Try another search or add a vehicle.</p></div></td></tr>`; return items.map((v, i) => `<tr><td><div class="vehicle-cell"><span class="vehicle-thumb">${v.imageData ? `<img src="${esc(v.imageData)}" alt="" loading="lazy">` : svg("truck")}</span><span class="vehicle-name"><strong>${esc(v.name)}</strong><small>${esc(v.plate)}</small></span></div></td><td><div class="avatar-stack">${avatar(v.driver, ["", "a2", "a3"][i % 3])}<span>${esc(v.driver || "Unassigned")}</span></div></td><td>${statusPill(v.status)}</td><td>${prettyDate(v.nextService, { day: "numeric", month: "short" })}</td><td><div class="usage-cell"><span class="usage-bar"><span style="width:${Math.min(100, Number(v.utilization || 0))}%"></span></span><small>${Number(v.utilization || 0)}%</small></div></td></tr>`).join(""); }
function docsList(items) { return items.map((d, i) => { const days = dayDistance(d.expiresOn); const typeClass = i % 3 === 1 ? "blue" : i % 3 === 2 ? "green" : ""; const expiryClass = days <= 7 ? "" : days <= 21 ? "soon" : "ok"; return `<div class="doc-row"><span class="doc-icon ${typeClass}">${svg(d.type.toLowerCase().includes("licence") ? "users" : "file")}</span><span class="doc-info"><strong>${esc(d.title)}</strong><small>${esc(d.entity)} · ${prettyDate(d.expiresOn, { day: "numeric", month: "short" })}</small></span><span class="expiry ${expiryClass}">${days < 0 ? "Expired" : days === 0 ? "Today" : `${days} days`}</span></div>`; }).join(""); }
function miniPayment(item) { const cls = item.status === "Paid" ? "" : "waiting"; return `<div class="doc-row payment-mini"><span class="doc-icon green">${svg("wallet")}</span><span class="doc-info"><strong>${esc(item.partner)}</strong><small>${esc(item.reference)} · ${prettyDate(item.dueOn, { day: "numeric", month: "short" })}</small></span><span class="pill-payment ${cls}">${money(item.amount, true)}</span></div>`; }
function dashboardView() { const active = data.vehicles.filter(v => v.status === "On route").length; const activeDrivers = data.drivers.filter(d => d.active !== false).length; const unpaid = data.payments.filter(p => p.status !== "Paid").reduce((sum, p) => sum + Number(p.amount), 0); const revenue = data.invoices.filter(i => i.status === "Paid").reduce((sum, i) => sum + Number(i.amount), 0); const today = new Intl.DateTimeFormat("en-IN", { weekday: "long", day: "numeric", month: "long", year: "numeric" }).format(new Date());
  return `${heading(`Today, ${today}`, "Your vehicles at a glance", "Here’s what is happening across Sauto Transport today.", `<button class="select-control" data-action="period">This month⌄</button>${button("Add vehicle", "add-vehicle", true, "plus")}`)}${hero()}<div class="stats-grid">${stat("Total vehicles", data.vehicles.length, "+2.4%", "vs. last month", "truck")}${stat("On the road", active, "+1 vehicle", "out on delivery", "chart", "orange")}${stat("Active drivers", activeDrivers, "+3 drivers", "ready for routes", "users", "blue")}${stat("Collected revenue", money(revenue, true), "+8.2%", "vs. last month", "wallet", "violet", false, "0,18 9,16 18,10 27,12 36,6 45,8 54,0")}</div><div class="dashboard-grid"><div class="stack"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Vehicle activity</h2><p class="panel-subtitle">Daily activity across your vehicles</p></div><div class="range-tabs"><button class="${reportRange === "Week" ? "selected" : ""}" data-range="Week">Week</button><button class="${reportRange === "Month" ? "selected" : ""}" data-range="Month">Month</button></div></div><div class="chart-summary"><strong>82.4%</strong><span>↗ 6.3% vs. previous period</span></div><div class="chart-wrap"><div class="chart-ylabels"><span>100%</span><span>75%</span><span>50%</span><span>25%</span></div>${activityChart()}</div><div class="chart-legend"><i></i> Vehicle activity <span style="margin-left:auto">Updated just now</span></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Your vehicles</h2><p class="panel-subtitle">A quick look at your active vehicles</p></div><button class="text-link" data-nav="fleet">View all ${svg("arrow")}</button></div><div class="table-wrap"><table class="fleet-table"><thead><tr><th>Vehicle</th><th>Assigned driver</th><th>Status</th><th>Next service</th><th>Utilization</th></tr></thead><tbody>${vehicleRows(filtered(data.vehicles, ["name", "plate", "driver"]).slice(0, 4))}</tbody></table></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Documents to renew</h2><p class="panel-subtitle">Stay ahead of upcoming expiries</p></div><button class="text-link" data-nav="documents">All documents ${svg("arrow")}</button></div><div class="doc-list">${docsList([...data.documents].sort((a, b) => a.expiresOn.localeCompare(b.expiresOn)).slice(0, 4))}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Recent payments</h2><p class="panel-subtitle">${money(unpaid, true)} outstanding across suppliers</p></div><button class="text-link" data-nav="payments">See all ${svg("arrow")}</button></div><div class="doc-list">${[...data.payments].slice(0, 3).map(miniPayment).join("")}</div></section><section class="panel quick-report"><div class="panel-head"><div><h2 class="panel-title">Operations snapshot</h2><p class="panel-subtitle">A healthy day for your vehicles</p></div><span class="stat-icon">${svg("chart")}</span></div><div class="snapshot-row"><span>On-time deliveries</span><strong>96.8%</strong></div><div class="snapshot-row"><span>Fuel efficiency</span><strong>8.4 <small>km/L</small></strong></div><div class="snapshot-row"><span>Open invoices</span><strong>${data.invoices.filter(i => i.status !== "Paid").length}</strong></div><button class="text-link" data-nav="reports">Open full report ${svg("arrow")}</button></section></div></div>`; }

function vehicleIllustration(v, i) { return `<div class="vehicle-illustration"><div class="van-body"></div><div class="van-cabin"><div class="van-window"></div></div><div class="van-stripe"></div><div class="van-mark">sauto.</div><div class="van-wheel one"></div><div class="van-wheel two"></div></div>`; }
function fleetView() {
  const list = filtered(data.vehicles, ["name", "plate", "category", "driver"]).filter(v => fleetFilter === "All vehicles" || v.status === fleetFilter);
  const actions = `${button("Export", "export-vehicles", false, "download")}${button("Add vehicle", "add-vehicle", true, "plus")}`;
  const cards = list.map((v, i) => {
    const photo = v.imageData ? `<img class="vehicle-photo" src="${esc(v.imageData)}" alt="${esc(v.name)}" loading="lazy">` : vehicleIllustration(v, i);
    return `<article class="asset-card">
      <div class="asset-visual ${esc(v.tone || ["green", "blue", "sand"][i % 3])}">
        <span class="asset-tag">${esc(v.category || "Transport vehicle").toUpperCase()}</span>
        ${photo}
        <button class="asset-photo-link" data-action="vehicle-menu" data-id="${esc(v.id)}">${v.imageData ? "Edit details" : `${svg("plus")} Add photo`}</button>
        <button class="icon-button asset-more" data-action="vehicle-menu" data-id="${esc(v.id)}" aria-label="Edit ${esc(v.name)}">${svg("more")}</button>
      </div>
      <div class="asset-card-head"><div><h3>${esc(v.name)}</h3><p>${esc(v.plate)}</p></div>${statusPill(v.status)}</div>
      <div class="asset-meta">
        <div><span>Driver</span><strong>${esc(v.driver || "Unassigned")}</strong></div>
        <div><span>Next service</span><strong>${prettyDate(v.nextService, { day: "numeric", month: "short" })}</strong></div>
        <div><span>Odometer</span><strong>${Number(v.mileage || 0).toLocaleString("en-IN")} km</strong></div>
        <div><span>In use</span><strong>${Number(v.utilization || 0)}%</strong></div>
      </div>
      <div class="asset-footer"><div class="avatar-stack">${avatar(v.driver || "Unassigned")}<small>${esc(v.driver || "Unassigned")}</small></div><span class="usage-cell"><span class="usage-bar"><span style="width:${Math.min(100, Number(v.utilization || 0))}%"></span></span><small>${Number(v.utilization || 0)}%</small></span></div>
    </article>`;
  }).join("");
  return `${heading("Vehicle management", "Vehicles", "See each vehicle, its driver and upcoming service date.", actions)}
    <section class="panel">
      <div class="panel-toolbar"><label class="toolbar-search">${svg("search")}<input type="search" data-local-search placeholder="Search vehicles, plates or drivers" value="${esc(currentQuery)}"/></label><div class="toolbar-actions"><select class="select-control" data-filter-select aria-label="Filter vehicles"><option>All vehicles</option><option ${fleetFilter === "On route" ? "selected" : ""}>On route</option><option ${fleetFilter === "Available" ? "selected" : ""}>Available</option><option ${fleetFilter === "Service" ? "selected" : ""}>Service</option></select></div></div>
      ${list.length ? `<div class="fleet-grid">${cards}</div>` : `<div class="empty-state"><span class="empty-icon">${svg("truck")}</span><strong>No vehicles found</strong><p>Try changing your search or add a vehicle.</p>${button("Add a vehicle", "add-vehicle", true, "plus")}</div>`}
    </section>`;
}
function driversView() { const list = filtered(data.drivers, ["name", "phone", "email"]); return `${heading("People & assignments", "Drivers", "Your people make every delivery possible. Keep their details up to date.", `${button("Export list", "export-drivers", false, "download")}${button("Add driver", "add-driver", true, "plus")}`)}<section class="panel"><div class="panel-toolbar"><label class="toolbar-search">${svg("search")}<input type="search" data-local-search placeholder="Search drivers..." value="${esc(currentQuery)}"/></label><div class="toolbar-actions"><span class="list-total">${data.drivers.length} drivers in this workspace</span></div></div>${list.length ? `<div class="drivers-grid">${list.map(d => `<article class="driver-card"><div class="driver-top"><span class="driver-avatar ${esc(d.tone || "")}">${esc(initials(d.name))}</span><div class="driver-details"><strong>${esc(d.name)}</strong><small>${esc(d.email || d.phone || "Driver profile")}</small></div>${statusPill(d.active === false ? "Inactive" : "Active")}</div><div class="driver-card-stats"><div><span>Experience</span><strong>${esc(d.experience || "—")}</strong></div><div><span>Rating</span><strong class="driver-rating">★ ${esc(d.rating || "4.8")}</strong></div><div><span>Licence expiry</span><strong>${prettyDate(d.licenseExpiry, { day: "numeric", month: "short" })}</strong></div></div><div class="asset-footer"><div class="avatar-stack">${avatar(d.name)}<small>${esc(d.phone || "Contact not added")}</small></div><button class="text-link" data-action="driver-contact" data-id="${esc(d.id)}">View profile ${svg("arrow")}</button></div></article>`).join("")}</div>` : `<div class="empty-state"><span class="empty-icon">${svg("users")}</span><strong>No drivers found</strong><p>Try another search or add a driver profile.</p>${button("Add driver", "add-driver", true, "plus")}</div>`}</section>`; }
function documentTypeIcon(type) { return type?.toLowerCase().includes("licence") ? "users" : type?.toLowerCase().includes("insurance") ? "receipt" : "file"; }
function documentsView() { const list = filtered(data.documents, ["type", "entity", "title", "reference"]).sort((a, b) => a.expiresOn.localeCompare(b.expiresOn)); return `${heading("Compliance & reminders", "Documents", "Expiry dates are on your radar. Add a document to keep every vehicle road-ready.", `${button("Export register", "export-documents", false, "download")}${button("Add document", "add-document", true, "plus")}`)}<section class="panel"><div class="panel-toolbar"><label class="toolbar-search">${svg("search")}<input type="search" data-local-search placeholder="Search by vehicle, driver or document..." value="${esc(currentQuery)}"/></label><div class="toolbar-actions"><span class="list-total">${list.filter(d => dayDistance(d.expiresOn) <= 30).length} due within 30 days</span></div></div>${list.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Document</th><th>Assigned to</th><th>Reference</th><th>Expiry date</th><th>Reminder</th><th>Status</th></tr></thead><tbody>${list.map(d => { const days = dayDistance(d.expiresOn); return `<tr><td><div class="vehicle-cell"><span class="doc-icon">${svg(documentTypeIcon(d.type))}</span><span class="vehicle-name"><strong>${esc(d.title)}</strong><small>${esc(d.type)}</small></span></div></td><td>${esc(d.entity)}</td><td>${esc(d.reference || "—")}</td><td>${prettyDate(d.expiresOn)}</td><td><span class="expiry ${days > 21 ? "ok" : days > 7 ? "soon" : ""}">${relativeDate(d.expiresOn)}</span></td><td>${statusPill(days < 0 ? "Overdue" : days <= 30 ? "Expiring" : "Upcoming")}</td></tr>`; }).join("")}</tbody></table></div>` : `<div class="empty-state"><span class="empty-icon">${svg("file")}</span><strong>No documents found</strong><p>Keep expiry dates together by adding a document to your register.</p>${button("Add document", "add-document", true, "plus")}</div>`}</section><div class="panel" style="margin-top:14px;background:#f7f9f4"><div class="panel-head"><div><h2 class="panel-title">Automatic reminders</h2><p class="panel-subtitle">Sauto highlights documents due in the next 30 days and overdue renewals.</p></div><span class="stat-icon">${svg("bell")}</span></div><div class="snapshot-row"><span>Expiry alerts are visible on the dashboard</span><strong style="color:#63865b">On</strong></div></div>`; }
function paymentsView() { const list = filtered(data.payments, ["reference", "partner", "description", "method"]).filter(p => paymentFilter === "All payments" || p.status === paymentFilter); const outstanding = data.payments.filter(p => p.status !== "Paid").reduce((sum, p) => sum + Number(p.amount), 0); return `${heading("Cash flow", "Payments", "Track supplier payments, spot what’s due and keep operations moving.", `${button("Export payments", "export-payments", false, "download")}${button("Record payment", "add-payment", true, "plus")}`)}<div class="stats-grid">${stat("Due this week", money(outstanding, true), `${data.payments.filter(p => p.status !== "Paid").length} items`, "awaiting settlement", "wallet", "orange")}${stat("Paid this month", money(data.payments.filter(p => p.status === "Paid").reduce((s, p) => s + Number(p.amount), 0), true), "+5.1%", "vs. last month", "check")}${stat("Average settlement", "2.4 days", "−0.8 days", "faster than before", "clock", "blue")}${stat("Payment health", "94%", "+2.0%", "on-time settlements", "chart", "violet")}</div><section class="panel"><div class="panel-toolbar"><label class="toolbar-search">${svg("search")}<input type="search" data-local-search placeholder="Search suppliers or references..." value="${esc(currentQuery)}"/></label><div class="toolbar-actions"><select class="select-control" data-payment-filter aria-label="Filter payments"><option>All payments</option><option ${paymentFilter === "Pending" ? "selected" : ""}>Pending</option><option ${paymentFilter === "Paid" ? "selected" : ""}>Paid</option></select></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Supplier</th><th>Description</th><th>Due date</th><th>Method</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${list.length ? list.map(p => `<tr><td><strong style="color:#405045">${esc(p.reference)}</strong></td><td>${esc(p.partner)}</td><td>${esc(p.description)}</td><td>${prettyDate(p.dueOn)}</td><td>${esc(p.method || "—")}</td><td><strong style="color:#35463a">${money(p.amount)}</strong></td><td>${p.status === "Paid" ? `<span class="pill-payment">Paid</span>` : `<span class="pill-payment waiting">Pending</span>`}</td><td>${p.status !== "Paid" ? `<button class="text-link" data-action="mark-payment" data-id="${esc(p.id)}">Mark paid</button>` : ""}</td></tr>`).join("") : `<tr><td colspan="8"><div class="empty-state"><strong>No payments found</strong><p>Try adjusting your search or add a new payment.</p></div></td></tr>`}</tbody></table></div></section>`; }
function billingView() { const open = data.invoices.filter(i => i.status !== "Paid"); const openAmount = open.reduce((s, i) => s + Number(i.amount), 0); const collected = data.invoices.filter(i => i.status === "Paid").reduce((s, i) => s + Number(i.amount), 0); const list = filtered(data.invoices, ["reference", "customer", "description", "status"]); return `${heading("Revenue & collections", "Billing", "Build a clear view of what’s invoiced, collected and still outstanding.", `${button("Download report", "export-invoices", false, "download")}${button("Create invoice", "add-invoice", true, "plus")}`)}<div class="stats-grid">${stat("Outstanding", money(openAmount, true), `${open.length} invoices`, "awaiting collection", "receipt", "orange")}${stat("Collected this month", money(collected, true), "+11.4%", "vs. last month", "wallet")}${stat("Overdue invoices", String(data.invoices.filter(i => i.status === "Overdue").length), "Needs attention", "past due date", "clock", "blue", true)}${stat("Collection rate", "91.6%", "+4.3%", "on-time collection", "chart", "violet")}</div><div class="report-grid" style="margin-bottom:15px"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Invoice activity</h2><p class="panel-subtitle">Created versus collected over the last 7 months</p></div><span class="chart-legend"><i></i> Collected <i style="background:#d9e7d3;margin-left:6px"></i> Invoiced</span></div>${reportBars([48, 64, 52, 83, 71, 92, 75])}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Collection focus</h2><p class="panel-subtitle">A few things to keep moving</p></div></div><div class="snapshot-row"><span>Overdue amount</span><strong>${money(data.invoices.filter(i => i.status === "Overdue").reduce((s, i) => s + Number(i.amount), 0), true)}</strong></div><div class="snapshot-row"><span>Next invoice due</span><strong>${open.length ? prettyDate(open[0].dueOn, { day: "numeric", month: "short" }) : "—"}</strong></div><div class="snapshot-row"><span>Average collection time</span><strong>18 <small>days</small></strong></div></section></div><section class="panel"><div class="panel-toolbar"><label class="toolbar-search">${svg("search")}<input type="search" data-local-search placeholder="Search invoices or customers..." value="${esc(currentQuery)}"/></label><div class="toolbar-actions"><span class="list-total">${data.invoices.length} invoices</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Customer</th><th>Description</th><th>Issued</th><th>Due date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${list.length ? list.map(i => `<tr><td><strong style="color:#405045">${esc(i.reference)}</strong></td><td>${esc(i.customer)}</td><td>${esc(i.description)}</td><td>${prettyDate(i.issuedOn)}</td><td>${prettyDate(i.dueOn)}</td><td><strong style="color:#35463a">${money(i.amount)}</strong></td><td><span class="pill-payment ${i.status === "Overdue" ? "late" : i.status === "Paid" ? "" : "waiting"}">${esc(i.status)}</span></td><td>${i.status !== "Paid" ? `<button class="text-link" data-action="mark-invoice" data-id="${esc(i.id)}">${i.status === "Overdue" ? "Mark paid" : "•••"}</button>` : ""}</td></tr>`).join("") : `<tr><td colspan="8"><div class="empty-state"><strong>No invoices found</strong><p>Create an invoice to start tracking collections here.</p></div></td></tr>`}</tbody></table></div></section>`; }
function reportBars(values = [49, 69, 58, 78, 65, 94, 77]) { const months = ["Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct"]; return `<div class="report-bars">${values.map((v, i) => `<div class="bar-group"><div class="bar-pair"><span class="bar" style="height:${Math.max(16, v - 13)}%"></span><span class="bar dark" style="height:${v}%"></span></div><small>${months[i]}</small></div>`).join("")}</div>`; }
function reportsView() { const paid = data.invoices.filter(i => i.status === "Paid").reduce((s, i) => s + Number(i.amount), 0); const costs = data.payments.reduce((s, p) => s + Number(p.amount), 0); return `${heading("Insights & exports", "Reports", "A clear read on vehicle activity, revenue and the work behind every delivery.", `<select class="select-control" data-report-range><option>Last 7 months</option><option>Last 30 days</option><option>Year to date</option></select>${button("Export report", "export-report", true, "download")}`)}<div class="report-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Revenue & vehicle activity</h2><p class="panel-subtitle">Monthly billing alongside deliveries completed</p></div><div class="chart-legend"><i></i> Revenue <i style="background:#d9e7d3;margin-left:7px"></i> Costs</div></div>${reportBars([54, 63, 58, 77, 68, 94, 82])}</section><section class="panel report-aside"><div class="report-kpi"><span>Revenue collected</span><strong>${money(paid || 426700, true)}</strong><small>↗ 8.2% this period</small></div><div class="report-kpi orange"><span>Vehicle operating cost</span><strong>${money(costs, true)}</strong><small>Fuel, service & settlements</small></div><div class="report-kpi"><span>Vehicle use</span><strong>82.4%</strong><small>↗ 6.3% vs. previous period</small></div></section></div><section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2 class="panel-title">Report library</h2><p class="panel-subtitle">Download a snapshot for your team or accounting workflow.</p></div></div><div class="doc-list">${[
    ["Vehicle activity", "Availability, usage and service schedule", "truck"], ["Payment summary", "Supplier settlements, pending amounts and due dates", "payments"], ["Revenue & invoices", "Collections, outstanding invoices and customer billing", "receipt"], ["Driver compliance", "Licence renewals and driver readiness", "users"]
  ].map(([title, desc, iconName]) => `<div class="doc-row"><span class="doc-icon green">${svg(iconName)}</span><span class="doc-info"><strong>${title}</strong><small>${desc}</small></span><button class="button" data-action="export-report">${svg("download")} Export</button></div>`).join("")}</div></section>`; }
function summaryCard(label, value, caption, iconName, tone = "") { return `<div class="report-kpi ${tone}"><span>${label}</span><strong>${value}</strong><small>${caption}</small></div>`; }

function openModal(kind, id = null) { if (kind === "connection") connectionDraft = { baseUrl: localStorage.getItem("sauto-api-url") || "", email: "", password: "" }; if (kind.startsWith("edit-")) editingId = id; const root = $("#modal-root"); root.innerHTML = modalTemplate(kind); document.body.style.overflow = "hidden"; const first = $(".modal-card input, .modal-card select", root); if (first) setTimeout(() => first.focus(), 40); }
function closeModal() { $("#modal-root").innerHTML = ""; document.body.style.overflow = ""; }
function field(label, name, type = "text", value = "", full = false, placeholder = "", selected = null) { const input = type === "select" ? `<select name="${name}" required>${(value || []).map(option => `<option ${selected === option ? "selected" : ""}>${esc(option)}</option>`).join("")}</select>` : `<input name="${name}" type="${type}" ${type === "password" ? "autocomplete=\"current-password\"" : ""} value="${esc(value)}" placeholder="${esc(placeholder)}" ${type === "number" ? `min="0" step="${name === "rating" ? "any" : "1"}"` : ""} required>`; return `<div class="field ${full ? "full" : ""}"><label for="f-${name}">${esc(label)}</label>${input.replace(`name="${name}"`, `name="${name}" id="f-${name}"`)}</div>`; }
function modalFrame(title, subtitle, form, actions, note = "") { return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-button" data-action="close-modal" aria-label="Close">${svg("close")}</button></header>${form}<div class="modal-error" id="modal-error"></div>${note ? `<p class="form-note">${note}</p>` : ""}${actions}</section></div>`; }
function formWrap(id, content, submitLabel) { return `<form class="modal-form" id="${id}"><div class="form-grid">${content}</div><div class="modal-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">${esc(submitLabel)}</button></div></form>`; }
function vehiclePhotoField(imageData = "") { return `<div class="field full photo-field"><label>Vehicle photo <span>Optional</span></label><input type="hidden" name="imageData" value="${esc(imageData)}"><label class="photo-drop ${imageData ? "has-photo" : ""}" for="f-photo">${imageData ? `<img class="photo-preview" src="${esc(imageData)}" alt="Current vehicle photo">` : `<span class="photo-placeholder">${svg("truck")}</span>`}<span class="photo-copy"><strong>${imageData ? "Change vehicle photo" : "Add a vehicle photo"}</strong><small>Choose an image · JPG, PNG or WebP</small></span><input id="f-photo" type="file" accept="image/*" data-vehicle-photo></label>${imageData ? `<button class="photo-remove" type="button" data-action="clear-photo">Remove photo</button>` : ""}</div>`; }
function modalTemplate(kind) {
  if (kind === "edit-vehicle") {
    const item = data.vehicles.find(v => String(v.id) === String(editingId)); if (!item) return "";
    const content = [field("Vehicle name", "name", "text", item.name), field("Registration number", "plate", "text", item.plate), field("Vehicle class", "category", "select", ["Heavy truck", "Light truck", "Mini truck", "Van", "Refrigerated"], false, "", item.category), field("Status", "status", "select", ["Available", "On route", "Service"], false, "", item.status), field("Assigned driver", "driver", "text", item.driver), field("Next service", "nextService", "date", item.nextService), field("Odometer (km)", "mileage", "number", item.mileage), field("Utilization (%)", "utilization", "number", item.utilization)].join("");
    return modalFrame("Edit vehicle", "Keep the details and photo up to date.", `<form class="modal-form" id="edit-form" data-entity="vehicle" data-id="${esc(item.id)}"><div class="form-grid">${content}${vehiclePhotoField(item.imageData || "")}</div><div class="modal-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">Save changes</button></div></form>`, "");
  }
  if (kind === "edit-driver") {
    const item = data.drivers.find(d => String(d.id) === String(editingId)); if (!item) return "";
    const activeValue = item.active === false ? "Inactive" : "Active";
    const content = [field("Full name", "name", "text", item.name), field("Phone number", "phone", "tel", item.phone), field("Email address", "email", "email", item.email), field("Driving licence expiry", "licenseExpiry", "date", item.licenseExpiry), field("Experience", "experience", "text", item.experience), field("Rating", "rating", "number", item.rating), field("Profile status", "active", "select", ["Active", "Inactive"], true, "", activeValue)].join("");
    return modalFrame("Edit driver", "Update contact and compliance information.", `<form class="modal-form" id="edit-form" data-entity="driver" data-id="${esc(item.id)}"><div class="form-grid">${content}</div><div class="modal-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">Save changes</button></div></form>`, "");
  }
  if (kind === "connection") {
    const liveText = apiSession ? "Live API connected" : "Demo mode stays local";
    const content = `${field("Backend API URL", "baseUrl", "url", connectionDraft?.baseUrl || "", true, "https://api.your-domain.com")}<div class="field full"><label for="f-email">Email address</label><input id="f-email" name="email" type="email" value="" placeholder="you@company.com" autocomplete="username" required></div><div class="field full"><label for="f-password">Password</label><input id="f-password" name="password" type="password" autocomplete="current-password" placeholder="Your account password" required></div>`;
    const form = formWrap("connection-form", content, authMode === "login" ? "Connect to live data" : "Create account");
    const extra = `${apiSession ? `<button class="auth-toggle" type="button" data-action="switch-demo">Switch back to Demo mode</button>` : `<button class="auth-toggle" type="button" data-action="auth-toggle">${authMode === "login" ? "New to Sauto? Create a live account" : "Already have an account? Sign in"}</button>`}<div class="auth-points"><span>${svg("check")} ${liveText}</span><span>${svg("check")} Secure API session</span></div>`;
    return modalFrame("Connect your workspace", "Your live backend is deployed separately. Demo mode is available anytime.", form, extra, authMode === "register" ? "Create a live account with a password of at least 10 characters. Credentials are sent only to the backend URL above." : "Use the backend URL provided by your administrator. Live credentials are sent only to that backend; they are never saved in demo mode.");
  }
  const forms = {
    "add-vehicle": ["Add a vehicle", "Add a vehicle to your records.", [field("Vehicle name", "name", "text", "", false, "e.g. Tata Prima 5530.S"), field("Registration number", "plate", "text", "", false, "KA 03 MN 4821"), field("Vehicle class", "category", "select", ["Heavy truck", "Light truck", "Mini truck", "Van", "Refrigerated" ]), field("Status", "status", "select", ["Available", "On route", "Service"]), field("Assigned driver", "driver", "text", "", false, "Driver name"), field("Next service", "nextService", "date", isoOffset(30)), field("Odometer (km)", "mileage", "number", "0"), field("Utilization (%)", "utilization", "number", "70"), vehiclePhotoField()], "Save vehicle"],
    "add-driver": ["Add a driver", "Create a profile and keep renewals on your radar.", [field("Full name", "name", "text", "", false, "Driver name"), field("Phone number", "phone", "tel", "", false, "+91 98765 43210"), field("Email address", "email", "email", "", false, "name@company.com"), field("Driving licence expiry", "licenseExpiry", "date", isoOffset(180)), field("Experience", "experience", "text", "", false, "e.g. 5 years"), field("Rating", "rating", "number", "4.8")], "Save driver"],
    "add-document": ["Add a document", "Register an expiry date and let Sauto flag it in advance.", [field("Document type", "type", "select", ["Insurance", "Driving licence", "Fitness certificate", "Permit", "Pollution certificate", "Other"]), field("Assigned to", "entity", "text", "", false, "Vehicle or driver name"), field("Document name", "title", "text", "", true, "e.g. Commercial vehicle cover"), field("Reference number", "reference", "text", "", true, "Optional policy or certificate ID"), field("Expires on", "expiresOn", "date", isoOffset(30)), field("Status", "status", "select", ["Upcoming", "Expiring"])], "Save document"],
    "add-payment": ["Record a payment", "Keep supplier settlements visible to the whole team.", [field("Supplier", "partner", "text", "", false, "Supplier name"), field("Reference", "reference", "text", "", false, "PAY-2026-042"), field("Description", "description", "text", "", true, "What is this payment for?"), field("Amount (₹)", "amount", "number", "0"), field("Due date", "dueOn", "date", isoOffset(7)), field("Payment method", "method", "select", ["Bank transfer", "NEFT", "UPI", "Fuel card", "Cash"])], "Save payment"],
    "add-invoice": ["Create an invoice", "Add a customer bill and monitor its collection.", [field("Customer", "customer", "text", "", false, "Customer or company"), field("Invoice number", "reference", "text", "", false, "INV-2026-042"), field("Description", "description", "text", "", true, "Service or delivery summary"), field("Amount (₹)", "amount", "number", "0"), field("Issue date", "issuedOn", "date", isoOffset(0)), field("Due date", "dueOn", "date", isoOffset(14)), field("Status", "status", "select", ["Sent", "Paid"])], "Save invoice"]
  };
  if (kind === "notifications") return modalFrame("Your reminders", "A few things that may need your attention.", `<div class="modal-form"><div class="doc-list">${docsList([...data.documents].sort((a, b) => a.expiresOn.localeCompare(b.expiresOn)).slice(0, 4))}</div></div>`, `<div class="modal-actions" style="padding:0 22px 19px"><button class="button" data-nav="documents">View all documents ${svg("arrow")}</button><button class="button primary" data-action="close-modal">Done</button></div>`);
  if (kind === "profile") return modalFrame("Your Sauto workspace", "Profile and workspace settings.", `<div class="modal-form"><div class="doc-list"><div class="doc-row"><span class="profile-avatar">AM</span><span class="doc-info"><strong>Alex Morgan</strong><small>Transport manager · Sauto Transport</small></span></div><div class="doc-row"><span class="doc-icon green">${svg("settings")}</span><span class="doc-info"><strong>Workspace preferences</strong><small>Demo data is stored only in this browser.</small></span></div></div></div>`, `<div class="modal-actions" style="padding:0 22px 19px"><button class="button" data-action="connection">${apiSession ? "Live data settings" : "Connect a backend"}</button><button class="button primary" data-action="close-modal">Done</button></div>`);
  if (!forms[kind]) return "";
  const [title, subtitle, fields, submit] = forms[kind];
  return modalFrame(title, subtitle, formWrap("record-form", fields.join(""), submit), "", "");
}

function toast(message, iconName = "check") { const item = document.createElement("div"); item.className = "toast"; item.innerHTML = `${svg(iconName)}<span>${esc(message)}</span>`; $("#toast-stack").append(item); setTimeout(() => item.remove(), 3300); }
function showModalError(message) { const el = $("#modal-error"); if (el) { el.textContent = message; el.classList.add("show"); } }
async function handleVehiclePhoto(input) {
  const file = input.files?.[0]; if (!file) return;
  if (!file.type.startsWith("image/")) { toast("Choose an image file.", "close"); input.value = ""; return; }
  if (file.size > 12 * 1024 * 1024) { toast("Choose an image under 12 MB.", "close"); input.value = ""; return; }
  try {
    const bitmap = await createImageBitmap(file); const scale = Math.min(1, 960 / bitmap.width, 620 / bitmap.height);
    const canvas = document.createElement("canvas"); canvas.width = Math.round(bitmap.width * scale); canvas.height = Math.round(bitmap.height * scale);
    const context = canvas.getContext("2d"); context.fillStyle = "#fff"; context.fillRect(0, 0, canvas.width, canvas.height); context.imageSmoothingQuality = "high"; context.drawImage(bitmap, 0, 0, canvas.width, canvas.height); bitmap.close();
    const imageData = canvas.toDataURL("image/jpeg", .7); const form = input.closest("form");
    form.querySelector('[name="imageData"]').value = imageData;
    const drop = input.closest(".photo-drop"); drop.classList.add("has-photo");
    let preview = drop.querySelector(".photo-preview");
    if (!preview) { preview = document.createElement("img"); preview.className = "photo-preview"; preview.alt = "Selected vehicle photo"; drop.prepend(preview); }
    preview.src = imageData;
    const copy = drop.querySelector(".photo-copy"); if (copy) copy.querySelector("strong").textContent = "Change vehicle photo";
    if (!form.querySelector("[data-action='clear-photo']")) { const remove = document.createElement("button"); remove.type = "button"; remove.className = "photo-remove"; remove.dataset.action = "clear-photo"; remove.textContent = "Remove photo"; input.closest(".photo-field").append(remove); }
  } catch { toast("That photo could not be opened. Try a JPG or PNG image.", "close"); input.value = ""; }
}
async function apiFetch(path, options = {}) { const base = (localStorage.getItem("sauto-api-url") || "").replace(/\/$/, ""); if (!base) throw new Error("Add your backend API URL first."); const response = await fetch(`${base}${path}`, { ...options, headers: { "Content-Type": "application/json", ...(apiSession ? { Authorization: `Bearer ${apiSession.token}` } : {}), ...(options.headers || {}) } }); const text = await response.text(); let body = null; try { body = text ? JSON.parse(text) : null; } catch { body = text; } if (!response.ok) throw new Error(body?.message || body?.error || body?.detail || body?.title || `API request failed (${response.status}).`); return body; }
async function refreshLiveData() { const [vehicles, drivers, documents, payments, invoices] = await Promise.all(Object.entries(routes).map(async ([key, path]) => [key, await apiFetch(path)])); for (const [key, value] of [vehicles, drivers, documents, payments, invoices]) data[key] = Array.isArray(value) ? value : []; render(); }
function exportCsv(name, rows) { if (!rows?.length) { toast("There’s nothing to export yet.", "download"); return; } const headers = [...new Set(rows.flatMap(row => Object.keys(row)))]; const csv = [headers.join(","), ...rows.map(row => headers.map(key => `"${String(row[key] ?? "").replace(/"/g, '""')}"`).join(","))].join("\r\n"); const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); link.download = `${name}-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 1000); toast(`${name} exported.`, "download"); }
const exportMap = { "export-vehicles": ["vehicles", "vehicles"], "export-drivers": ["drivers", "drivers"], "export-documents": ["documents", "documents"], "export-payments": ["payments", "payments"], "export-invoices": ["invoices", "invoices"], "export-report": ["operations-report", null] };
function goToView(view) { activeView = view; currentQuery = ""; $("#global-search").value = ""; closeModal(); menuOpen = false; $("#sidebar").classList.remove("mobile-open"); $(".mobile-scrim").classList.remove("visible"); $(".mobile-more-backdrop").classList.remove("open"); $("[data-action='more-nav']")?.setAttribute("aria-expanded", "false"); render(); window.scrollTo({ top: 0, behavior: "smooth" }); }
async function handleAction(action, element) {
  if (action === "close-modal") return closeModal();
  if (action === "backdrop-close") return;
  if (action === "clear-photo") { const form = element.closest("form"); form.querySelector('[name="imageData"]').value = ""; const file = form.querySelector("[data-vehicle-photo]"); if (file) file.value = ""; const drop = form.querySelector(".photo-drop"); drop.classList.remove("has-photo"); drop.querySelector(".photo-preview")?.remove(); const copy = drop.querySelector(".photo-copy"); if (copy) copy.querySelector("strong").textContent = "Add a vehicle photo"; element.remove(); return; }
  if (action === "more-nav") { const open = $(".mobile-more-backdrop").classList.toggle("open"); element.setAttribute("aria-expanded", String(open)); return; }
  if (action === "close-more-nav") { $(".mobile-more-backdrop").classList.remove("open"); $("[data-action='more-nav']")?.setAttribute("aria-expanded", "false"); return; }
  if (action === "menu") { menuOpen = !menuOpen; $("#sidebar").classList.toggle("mobile-open", menuOpen); $(".mobile-scrim").classList.toggle("visible", menuOpen); return; }
  if (action === "close-menu") { $("#sidebar").classList.remove("mobile-open"); $(".mobile-scrim").classList.remove("visible"); return; }
  if (action === "connection") { authMode = "login"; return openModal("connection"); }
  if (action === "profile" || action === "notifications") return openModal(action);
  if (action === "auth-toggle") { authMode = authMode === "login" ? "register" : "login"; return openModal("connection"); }
  if (action === "switch-demo") { try { if (apiSession) await apiFetch("/api/auth/logout", { method: "POST" }); } catch {} apiSession = null; data = loadDemoData(); closeModal(); render(); toast("You’re back in Demo mode. Live data stays on your backend."); return; }
  const modalKinds = { "add-vehicle": "add-vehicle", "add-driver": "add-driver", "add-document": "add-document", "add-payment": "add-payment", "add-invoice": "add-invoice" };
  if (modalKinds[action]) return openModal(modalKinds[action]);
  if (action.startsWith("export-") && exportMap[action]) { const [name, key] = exportMap[action]; return exportCsv(name, key ? data[key] : [...data.vehicles, ...data.drivers, ...data.payments, ...data.invoices]); }
  if (action === "period") { toast("Your overview is showing this month."); return; }
  if (action === "edit-vehicle" || action === "vehicle-menu") return openModal("edit-vehicle", element.dataset.id);
  if (action === "edit-driver" || action === "driver-contact") return openModal("edit-driver", element.dataset.id);
  if (action === "mark-payment" || action === "mark-invoice") {
    const key = action === "mark-payment" ? "payments" : "invoices"; const endpoint = action === "mark-payment" ? "/api/payments" : "/api/invoices"; const item = data[key].find(row => String(row.id) === element.dataset.id); if (!item) return;
    try { if (apiSession) { await apiFetch(`${endpoint}/${encodeURIComponent(item.id)}/paid`, { method: "PATCH" }); await refreshLiveData(); } else { item.status = "Paid"; item.paidOn = isoOffset(0); saveDemo(); render(); } toast("Marked as paid. Your records are up to date."); } catch (error) { toast(error.message, "close"); }
    return;
  }
  if (action === "reset-demo") { data = structuredClone(seed); saveDemo(); render(); toast("Demo workspace reset."); }
}

async function handleSubmit(e) {
  if (e.target.id === "connection-form") {
    e.preventDefault(); const form = new FormData(e.target); const baseUrl = String(form.get("baseUrl")).trim().replace(/\/$/, ""); const email = String(form.get("email")).trim(); const password = String(form.get("password"));
    if (!baseUrl) return showModalError("Enter the URL where your backend API is deployed.");
    localStorage.setItem("sauto-api-url", baseUrl); connectionDraft = { baseUrl, email };
    const previousSession = apiSession;
    try { const endpoint = authMode === "login" ? "/api/auth/login" : "/api/auth/register"; const body = await apiFetch(endpoint, { method: "POST", body: JSON.stringify({ email, password, name: email.split("@")[0] }) }); apiSession = { token: body.token, user: body.user }; await refreshLiveData(); closeModal(); toast(authMode === "login" ? "Connected to your live workspace." : "Live account created and connected."); }
    catch (error) { apiSession = previousSession; showModalError(error.message || "Could not connect to the backend. Check the URL and account details."); }
    return;
  }
  if (e.target.id !== "record-form") return;
  e.preventDefault(); const form = new FormData(e.target); const kind = e.target.closest(".modal-card").querySelector("#modal-title").textContent;
  const settings = {
    "Add a vehicle": { key: "vehicles", endpoint: routes.vehicles, fields: ["name", "plate", "category", "status", "driver", "nextService", "mileage", "utilization", "imageData"], defaults: { id: crypto.randomUUID(), tone: ["green", "blue", "sand"][Math.floor(Math.random() * 3)] } },
    "Add a driver": { key: "drivers", endpoint: routes.drivers, fields: ["name", "phone", "email", "licenseExpiry", "experience", "rating"], defaults: { id: crypto.randomUUID(), active: true } },
    "Add a document": { key: "documents", endpoint: routes.documents, fields: ["type", "entity", "title", "reference", "expiresOn", "status"], defaults: { id: crypto.randomUUID() } },
    "Record a payment": { key: "payments", endpoint: routes.payments, fields: ["partner", "reference", "description", "amount", "dueOn", "method"], defaults: { id: crypto.randomUUID(), status: "Pending", paidOn: "" } },
    "Create an invoice": { key: "invoices", endpoint: routes.invoices, fields: ["customer", "reference", "description", "amount", "issuedOn", "dueOn", "status"], defaults: { id: crypto.randomUUID() } }
  }[kind];
  if (!settings) return;
  const item = { ...settings.defaults }; for (const fieldName of settings.fields) { const value = form.get(fieldName); item[fieldName] = ["amount", "mileage", "utilization", "rating"].includes(fieldName) ? Number(value || 0) : String(value || "").trim(); }
  if (kind === "Add a document") item.status = dayDistance(item.expiresOn) <= 30 ? "Expiring" : "Upcoming";
  if (kind === "Create an invoice" && dayDistance(item.dueOn) < 0) item.status = "Overdue";
  if (apiSession) {
    try { const payload = { ...item }; delete payload.id; delete payload.tone; if (payload.paidOn === "") delete payload.paidOn; await apiFetch(settings.endpoint, { method: "POST", body: JSON.stringify(payload) }); await refreshLiveData(); closeModal(); toast(`${kind.replace(/^(Add a |Record a |Create an )/, "")} saved to your live workspace.`); }
    catch (error) { showModalError(error.message); }
  } else { data[settings.key].unshift(item); saveDemo(); closeModal(); render(); toast(`${kind.replace(/^(Add a |Record a |Create an )/, "")} saved in demo mode.`); }
}

async function handleEditSubmit(e) {
  if (e.target.id !== "edit-form") return;
  e.preventDefault(); const form = new FormData(e.target); const type = e.target.dataset.entity; const id = e.target.dataset.id;
  const item = type === "vehicle" ? data.vehicles.find(row => String(row.id) === id) : data.drivers.find(row => String(row.id) === id);
  if (!item) return showModalError("This record is no longer available.");
  const body = Object.fromEntries(form.entries()); delete body.photo;
  if (type === "vehicle") { body.mileage = Number(body.mileage); body.utilization = Number(body.utilization); }
  else { body.active = body.active === "Active"; body.rating = Number(body.rating); }
  try {
    if (apiSession) { await apiFetch(`${type === "vehicle" ? routes.vehicles : routes.drivers}/${encodeURIComponent(id)}`, { method: "PUT", body: JSON.stringify(body) }); await refreshLiveData(); }
    else { Object.assign(item, body); saveDemo(); render(); }
    closeModal();
    toast(`${type === "vehicle" ? "Vehicle" : "Driver"} details updated.`);
  } catch (error) { showModalError(error.message); }
}

$("#app").addEventListener("click", async e => {
  const backdrop = e.target.closest(".modal-backdrop"); if (backdrop && e.target === backdrop) { closeModal(); return; }
  const nav = e.target.closest("[data-nav]"); if (nav) { e.preventDefault(); return goToView(nav.dataset.nav); }
  const actionElement = e.target.closest("[data-action]"); if (actionElement) { if (actionElement.classList.contains("mobile-more-backdrop") && e.target !== actionElement) return; e.preventDefault(); return handleAction(actionElement.dataset.action, actionElement); }
  const range = e.target.closest("[data-range]"); if (range) { reportRange = range.dataset.range; renderContent(); }
});
$("#app").addEventListener("input", e => { if (e.target.id === "global-search" || e.target.matches("[data-local-search]")) { currentQuery = e.target.value; if (e.target.id === "global-search") { if (currentQuery) { activeView = "fleet"; $("#breadcrumb-current").textContent = titles.fleet; $$("[data-nav]").forEach(b => b.classList.toggle("active", b.dataset.nav === "fleet")); } } renderContent(); const target = $(e.target.id === "global-search" ? "#global-search" : "[data-local-search]"); if (target) { target.focus(); target.setSelectionRange?.(currentQuery.length, currentQuery.length); } } });
$("#app").addEventListener("change", e => { if (e.target.matches("[data-vehicle-photo]")) { handleVehiclePhoto(e.target); return; } if (e.target.matches("[data-filter-select]")) { fleetFilter = e.target.value; renderContent(); } if (e.target.matches("[data-payment-filter]")) { paymentFilter = e.target.value; renderContent(); } if (e.target.matches("[data-report-range]")) { reportRange = e.target.value; renderContent(); } });
$("#app").addEventListener("submit", e => { if (e.target.id === "edit-form") handleEditSubmit(e); else handleSubmit(e); });
$("#app").addEventListener("keydown", e => { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") { e.preventDefault(); $("#global-search").focus(); } if (e.key === "Escape") closeModal(); });

render();
